    action.PCreature.m_pItem = &poorBuyer;
    action.PerformAction();
    ok = ok && g_createCalls == 3 && g_setTextCalls == 2 && stats.m_calls == 3;
    action.PCreature.m_pItem = &buyer;

    // dead or missing target: nothing
    target.m_flags91 = 1;
    action.PerformAction();
